-- North Indian: 21 recipes
insert into "CozyCookBookSchema".folders (id, name, blurb, user_id, is_public, position) values
  ('66ab5e4a-a637-5936-ad43-2cef455a60ca', 'North Indian', 'Punjabi and Mughlai cooking: slow-browned onions, whole spices, and gravies that take their time.', null, true, 2048)
on conflict (id) do update set name = excluded.name, blurb = excluded.blurb;

insert into "CozyCookBookSchema".recipes
  (id, title, ingredients, steps, folder_id, user_id, meal, is_public, position)
select r.id, r.title,
  (select coalesce(jsonb_agg(jsonb_build_object('id', gen_random_uuid(), 'name', n, 'isChecked', false) order by o), '[]'::jsonb)
   from unnest(r.ing) with ordinality as t(n, o)),
  (select coalesce(jsonb_agg(jsonb_build_object('id', gen_random_uuid(), 'text', st, 'isChecked', false) order by o), '[]'::jsonb)
   from unnest(r.steps) with ordinality as t(st, o)),
  '66ab5e4a-a637-5936-ad43-2cef455a60ca', null, r.meal, true, r.pos
from (values
  ('9cad9271-f3e9-52c1-ae13-7f6d818824b8'::uuid, 'Aloo Paratha', array['2 cups whole wheat flour','3 russet potatoes, boiled and mashed','1 yellow onion, minced','2 green chilies, minced','1 tsp ground cumin','1 tsp garam masala','1/4 cup fresh cilantro','4 tbsp ghee','Salt to taste'], array['Knead a soft dough with the flour, water and a little salt; rest 30 minutes.','Mix the mashed potato with onion, chilies, spices and cilantro.','Stuff each ball of dough with filling and seal it carefully.','Roll gently and cook on a hot tawa with ghee until both sides blister.','Serve with yogurt and pickle.'], 'Breakfast', 0),
  ('33e9b5aa-7650-56f2-96a5-e2a259f8192b'::uuid, 'Chole Bhature', array['2 cups chickpeas, soaked overnight','2 yellow onions, pureed','3 tomatoes, pureed','2 tbsp ginger garlic paste','2 tsp chole masala','1 tsp ground turmeric','2 cups all-purpose flour','1/2 cup yogurt','1/4 cup ghee','Oil for frying'], array['Pressure-cook the chickpeas with a tea bag for colour, then discard the bag.','Fry the onion puree until it darkens properly, then the ginger garlic paste.','Add the tomato puree and spices and cook until the oil separates.','Add the chickpeas with their liquor and simmer 20 minutes.','For bhature, make a yogurt dough, rest two hours, and deep-fry until they balloon.'], 'Breakfast', 1024),
  ('8e12ce48-3125-5498-9f86-93eb924412ba'::uuid, 'Masala Chai', array['2 cups water','2 cups whole milk','3 tbsp black tea leaves','4 green cardamom pods','1 inch fresh ginger, grated','2 cloves','1 cinnamon stick','3 tbsp granulated sugar'], array['Crush the cardamom, cloves and cinnamon roughly.','Boil them in water with the ginger for five minutes.','Add the tea and boil two minutes more.','Add the milk and sugar and bring to a boil three times, pulling it off each time.','Strain from a height.'], 'Breakfast', 2048),
  ('2a432f34-d3fb-561b-8518-21504ca22b0a'::uuid, 'Poha', array['2 cups poha','1 yellow onion, diced','2 green chilies, slit','1 tsp mustard seeds','10 fresh curry leaves','1/2 tsp ground turmeric','2 tbsp peanuts','2 tbsp oil','1 lemon','1/4 cup fresh cilantro'], array['Rinse the poha in a sieve until just soft; never soak it.','Temper mustard seeds, curry leaves and peanuts in hot oil.','Add the onion and chilies and soften; then the turmeric.','Fold in the poha gently and steam covered two minutes.','Lemon and cilantro at the end.'], 'Breakfast', 3072),
  ('91dfc8fd-e900-5af9-bb78-762102ded5a6'::uuid, 'Rajma Chawal', array['2 cups kidney beans, soaked overnight','2 yellow onions, minced','3 tomatoes, pureed','2 tbsp ginger garlic paste','1 tsp ground cumin','1 tsp ground coriander','1 tsp garam masala','1/2 tsp ground turmeric','3 tbsp ghee','2 cups basmati rice'], array['Pressure-cook the beans until they crush easily between two fingers.','Brown the onions in ghee slowly — 15 minutes, not five.','Add ginger garlic paste, then tomato puree and spices; cook until the oil separates.','Add the beans with their cooking water and simmer 30 minutes.','Mash a ladleful against the side to thicken it. Serve over rice.'], 'Lunch', 4096),
  ('c246d857-ddd2-56c1-9032-7a1bfa42454a'::uuid, 'Chana Masala', array['2 cups chickpeas, cooked','1 yellow onion, minced','2 tomatoes, pureed','1 tbsp ginger garlic paste','2 tsp chana masala','1 tsp ground cumin','1/2 tsp ground turmeric','1 tsp amchur','3 tbsp oil','1/4 cup fresh cilantro'], array['Brown the onion well, then add the ginger garlic paste.','Add the tomato and ground spices, cooking until the mixture leaves the pan.','Add the chickpeas and a cup of water; simmer 20 minutes.','Finish with amchur for sourness and plenty of cilantro.'], 'Lunch', 5120),
  ('72b7e0a1-16c7-54cc-a2cd-c02093d14ac1'::uuid, 'Chicken Tikka Masala', array['2 lbs chicken thighs, cubed','1 cup yogurt','2 tbsp ginger garlic paste','2 tsp garam masala','1 tsp ground turmeric','2 tsp sweet paprika','1 yellow onion, minced','1 can crushed tomatoes','1 cup heavy cream','4 tbsp butter','1 tbsp kasuri methi'], array['Marinate the chicken in yogurt, ginger garlic paste and half the spices for four hours.','Grill or broil the chicken until charred at the edges. Char is the point.','Soften the onion in butter, add the remaining spices and the tomatoes.','Simmer 20 minutes, then blend smooth and return to the pan.','Add cream and the grilled chicken; simmer 10 minutes.','Crush the kasuri methi between your palms over the pan at the end.'], 'Dinner', 6144),
  ('57bb0e05-528d-5736-80b8-5729fe6c756c'::uuid, 'Butter Chicken', array['2 lbs chicken thighs','1 cup yogurt','2 tbsp ginger garlic paste','2 tsp garam masala','1 can crushed tomatoes','1 cup heavy cream','6 tbsp butter','1 tbsp honey','1 tsp kashmiri chili powder','1 tbsp kasuri methi'], array['Marinate and grill the chicken as for tikka.','Simmer the tomatoes with chili powder and butter for 25 minutes, then blend.','Pass the sauce through a sieve — this is what makes it velvety.','Add cream, honey and the chicken and warm through gently.','Finish with kasuri methi and a knob of cold butter.'], 'Dinner', 7168),
  ('0d98d49c-78da-5fee-a57f-2f8b41357dd4'::uuid, 'Rogan Josh', array['2 lbs lamb shoulder, cubed','1 cup yogurt','2 tsp kashmiri chili powder','1 tsp ground fennel','1 tsp ground ginger','4 green cardamom pods','2 black cardamom pods','1 cinnamon stick','4 tbsp ghee','1 pinch asafoetida'], array['Brown the lamb in ghee in batches and set aside.','Bloom the whole spices and asafoetida in the fat.','Whisk the yogurt and add it off the heat, a spoon at a time, so it does not split.','Return the lamb, cover, and cook 90 minutes until the sauce clings and reddens.'], 'Dinner', 8192),
  ('83682a96-3563-57ee-8883-dc57689da8c2'::uuid, 'Palak Paneer', array['1 lb paneer, cubed','2 lbs spinach','1 yellow onion, minced','2 green chilies','1 tbsp ginger garlic paste','1 tsp ground cumin','1/2 tsp garam masala','3 tbsp ghee','1/4 cup heavy cream'], array['Blanch the spinach 90 seconds and shock it in ice water — this keeps it green.','Blend with the green chilies to a coarse puree.','Brown the onion in ghee, add ginger garlic paste and the ground spices.','Add the spinach puree and cook only five minutes; longer turns it grey.','Fold in the paneer and cream.'], 'Dinner', 9216),
  ('0499f333-2af3-5616-a67e-5a540ba0d85a'::uuid, 'Dal Makhani', array['1 cup whole black urad dal','1/4 cup kidney beans','1 tbsp ginger garlic paste','2 tomatoes, pureed','4 tbsp butter','1/2 cup heavy cream','1 tsp garam masala','1 tsp kashmiri chili powder','1 tbsp kasuri methi'], array['Soak the dal and beans overnight, then pressure-cook until completely soft.','Fry the ginger garlic paste and tomato puree with the spices until the oil separates.','Combine and simmer on the lowest possible heat for two hours, stirring often.','Add butter and cream in the last 20 minutes.','The long slow cooking is the entire recipe. There is no shortcut.'], 'Dinner', 10240),
  ('bd208d18-8571-5301-b92d-104d0df09409'::uuid, 'Malai Kofta', array['1 cup paneer, grated','2 russet potatoes, boiled and mashed','3 tbsp cornstarch','2 tbsp raisins','2 tbsp cashews','Oil for frying','1 yellow onion, pureed','1/2 cup cashew paste','1 cup heavy cream','1 tsp garam masala','3 tbsp ghee'], array['Mix paneer, potato and cornstarch; stuff each ball with a raisin and a cashew.','Fry the kofta until golden and drain them.','Cook the onion puree in ghee without browning it — this gravy stays pale.','Add cashew paste, cream and garam masala and simmer gently.','Add the kofta only at the table, or they dissolve.'], 'Dinner', 11264),
  ('c6a7e9b5-e16e-55e5-ad80-8afa8855ce14'::uuid, 'Biryani', array['3 cups basmati rice','2 lbs chicken, bone-in','1 cup yogurt','3 yellow onions, sliced thin','1 pinch saffron threads','1/4 cup whole milk','2 tsp biryani masala','1/4 cup fresh mint','1/4 cup fresh cilantro','4 tbsp ghee','4 green cardamom pods'], array['Fry the onions slowly until deep brown and crisp; reserve half.','Marinate the chicken in yogurt, half the fried onions and the masala for two hours.','Parboil the rice with whole spices to 70 percent — it finishes in the steam.','Layer chicken, rice, herbs, saffron milk and the rest of the onions.','Seal the pot with dough or foil and cook on the lowest heat 25 minutes.','Do not stir it. Bring it to the table sealed and open it there.'], 'Dinner', 12288),
  ('56aa6103-69b0-5f69-b851-1db9de1943b4'::uuid, 'Baingan Bharta', array['2 large eggplants','1 yellow onion, minced','3 tomatoes, diced','1 tbsp ginger garlic paste','2 green chilies, minced','1 tsp ground cumin','1/2 tsp ground turmeric','3 tbsp oil','1/4 cup fresh cilantro'], array['Char the eggplants directly over a flame until the skin blackens and collapses.','Cool, peel, and mash the smoky flesh.','Brown the onion, add ginger garlic paste, chilies and tomatoes.','Cook until jammy, then fold in the eggplant and cook 10 minutes more.'], 'Dinner', 13312),
  ('01d7f54c-9b5f-5e1b-97c4-a6931914cae0'::uuid, 'Naan', array['3 cups all-purpose flour','1/2 cup yogurt','1 tsp active dry yeast','1 tsp granulated sugar','1/2 cup warm milk','3 tbsp ghee','1 tsp salt','1 tbsp nigella seeds'], array['Proof the yeast in the warm milk with the sugar.','Knead a soft dough with the flour, yogurt and salt; prove two hours.','Roll into teardrops and slap onto the hottest dry pan you own.','When it bubbles, flip and press. Brush with ghee and scatter nigella seeds.'], 'Snack', 14336),
  ('a9a5dcf4-4945-5852-8282-de6544da981e'::uuid, 'Jeera Rice', array['2 cups basmati rice','2 tsp cumin seeds','3 tbsp ghee','1 bay leaf','4 green cardamom pods','Salt to taste'], array['Rinse the rice until the water runs clear, then soak 30 minutes.','Bloom the cumin and whole spices in ghee until they crackle.','Add the drained rice and toast two minutes.','Add water at 1:1.5, boil, then cover and cook on the lowest heat 12 minutes.','Rest 10 minutes before fluffing.'], 'Snack', 15360),
  ('6b78724c-c6fb-5fc4-9d24-a00fa5fca24e'::uuid, 'Raita', array['2 cups yogurt','1 cucumber, grated','1/2 tsp ground cumin','1/4 cup fresh mint','1/4 tsp black salt','Salt to taste'], array['Squeeze the water out of the grated cucumber.','Whisk the yogurt smooth and fold everything together.','Toast and grind the cumin yourself if you can — it is most of the flavour.'], 'Snack', 16384),
  ('fe9c56ad-a22b-5525-9e5f-08012aaff4e8'::uuid, 'Samosa', array['2 cups all-purpose flour','1/4 cup ghee','4 russet potatoes, boiled','1 cup English peas','1 tsp ground cumin','1 tsp garam masala','1 tsp amchur','2 green chilies, minced','Oil for frying'], array['Rub the ghee into the flour until it holds shape when squeezed, then add water sparingly.','Rest the dough 30 minutes — a short dough gives the blistered shell.','Mash the potatoes coarsely with peas, spices and chilies.','Cut circles in half, form cones, fill and seal with water.','Fry at a low 300°F until pale, then again hot until deep gold.'], 'Snack', 17408),
  ('7f2f7aac-a4b4-533b-a8ee-e6f90a43beeb'::uuid, 'Gulab Jamun', array['1 cup milk powder','1/4 cup all-purpose flour','1/4 tsp baking powder','3 tbsp ghee','1/4 cup whole milk','2 cups granulated sugar','2 cups water','4 green cardamom pods','1 tbsp rose water'], array['Make a soft dough and rest it 10 minutes. Handle it as little as possible.','Roll crack-free balls — any seam splits in the oil.','Fry very gently at low heat, moving constantly, until deep brown.','Boil the sugar and water with cardamom into a thin syrup.','Drop the hot jamun into warm syrup and soak two hours.'], 'Snack', 18432),
  ('3981e8e3-1349-5c17-b8c2-d22fd09c6382'::uuid, 'Kheer', array['1/2 cup basmati rice','6 cups whole milk','1/2 cup granulated sugar','4 green cardamom pods','2 tbsp almonds, slivered','2 tbsp pistachios','1 pinch saffron threads'], array['Soak the rice 20 minutes, then drain.','Simmer it in the milk on low, stirring often, for 45 minutes until it thickens.','Add sugar only at the end — earlier and the rice stays hard.','Stir in cardamom, saffron and nuts. Good warm or cold.'], 'Snack', 19456),
  ('562367d0-d42b-5ea8-b499-3302f279e3ac'::uuid, 'Mango Lassi', array['2 cups yogurt','2 cups mango, diced','1/2 cup whole milk','3 tbsp granulated sugar','4 green cardamom pods, ground','Ice'], array['Blend everything until completely smooth.','Adjust with milk to a drinkable thickness.','Serve very cold with a pinch of ground cardamom on top.'], 'Snack', 20480)
) as r(id, title, ing, steps, meal, pos)
on conflict (id) do update set title = excluded.title, ingredients = excluded.ingredients, steps = excluded.steps, meal = excluded.meal;
